/// Builds an expression from an AST expression, looking up columns and
/// aggregate expressions in the scope.
pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
    match expr {
        ast::Expression::All => Err(errinput!("cannot use * in expression")),
        ast::Expression::Column(table, name) => {
            let idx = scope.lookup_column(table.as_deref(), &name)?;
            Ok(Expression::Column(idx))
        }
        ast::Expression::Literal(lit) => {
            Ok(Expression::Constant(match lit {
                ast::Literal::Null => Value::Null,
                ast::Literal::Boolean(b) => Value::Boolean(b),
                ast::Literal::Integer(i) => Value::Integer(i),
                ast::Literal::Float(f) => Value::Float(f),
                ast::Literal::String(s) => Value::String(s),
            }))
        }
        ast::Expression::Function(name, args) => {
            let args: Vec<Expression> = args
                .into_iter()
                .map(|e| Self::build_expression(e, scope))
                .collect::<Result<_>>()?;
            Ok(Expression::Function(name, args))
        }
        ast::Expression::Operator(op) => {
            Self::build_operator(op, scope)
        }
    }
}
